responses.text:
{
  "microtasks": [
    {
      "id": 1,
      "description": "Define the specific sub-themes of social media effects on teenagers to focus on (e.g., mental health, sleep quality, social relationships).",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Formulate search strings and keywords based on the identified sub-themes for database searching.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Conduct a literature search on academic databases for peer-reviewed articles concerning social media and teenage mental health.",
      "prerequisites": [2]
    },
    {
      "id": 4,
      "description": "Conduct a literature search on academic databases for peer-reviewed articles concerning social media and teenage sleep or academic performance.",
      "prerequisites": [2]
    },
    {
      "id": 5,
      "description": "Conduct a literature search on academic databases for peer-reviewed articles concerning social media and teenage social relationships.",
      "prerequisites": [2]
    },
    {
      "id": 6,
      "description": "Select and download 4-5 high-quality sources from the mental health search results.",
      "prerequisites": [3]
    },
    {
      "id": 7,
      "description": "Select and download 4-5 high-quality sources from the sleep/academic performance search results.",
      "prerequisites": [4]
    },
    {
      "id": 8,
      "description": "Select and download 4-5 high-quality sources from the social relationships search results.",
      "prerequisites": [5]
    },
    {
      "id": 9,
      "description": "Create a literature synthesis matrix spreadsheet with columns for author, methodology, key findings, and limitations.",
      "prerequisites": []
    },
    {
      "id": 10,
      "description": "Read the selected mental health articles and extract key findings, methodologies, and gaps into the synthesis matrix.",
      "prerequisites": [6, 9]
    },
    {
      "id": 11,
      "description": "Read the selected sleep/academic performance articles and extract key findings, methodologies, and gaps into the synthesis matrix.",
      "prerequisites": [7, 9]
    },
    {
      "id": 12,
      "description": "Read the selected social relationship articles and extract key findings, methodologies, and gaps into the synthesis matrix.",
      "prerequisites": [8, 9]
    },
    {
      "id": 13,
      "description": "Draft a detailed outline for the literature review section, organizing it by the chosen sub-themes.",
      "prerequisites": [10, 11, 12]
    },
    {
      "id": 14,
      "description": "Write the introductory paragraph of the literature review, establishing the context and outlining the structure of the section.",
      "prerequisites": [13]
    },
    {
      "id": 15,
      "description": "Write the subsection synthesizing the literature on mental health effects.",
      "prerequisites": [13, 10]
    },
    {
      "id": 16,
      "description": "Write the subsection synthesizing the literature on sleep and academic performance.",
      "prerequisites": [13, 11]
    },
    {
      "id": 17,
      "description": "Write the subsection synthesizing the literature on social relationships.",
      "prerequisites": [13, 12]
    },
    {
      "id": 18,
      "description": "Write the synthesis and gap analysis paragraph, explaining how the existing literature leads to your specific research question.",
      "prerequisites": [15, 16, 17]
    },
    {
      "id": 19,
      "description": "Format all in-text citations and compile the reference list according to the required academic style guide (e.g., APA).",
      "prerequisites": [14, 15, 16, 17, 18]
    },
    {
      "id": 20,
      "description": "Proofread the entire literature review draft for academic tone, clarity, and smooth transitions between sub-themes.",
      "prerequisites": [19]
    }
  ]
}
